module ariane_tiny_soc (
	clk_i,
	rst_ni,
	mem_req_o,
	mem_addr_o,
	mem_wdata_o,
	mem_strb_o,
	mem_we_o,
	mem_rdata_o
);
	parameter [31:0] NumWords = 1048576;
	parameter [31:0] AddrWidth = 64;
	parameter [31:0] DataWidth = 64;
	parameter [31:0] StrbWidth = DataWidth >> 3;
	input clk_i;
	input rst_ni;
	output mem_req_o;
	output [AddrWidth - 1:0] mem_addr_o;
	output [DataWidth - 1:0] mem_wdata_o;
	output [StrbWidth - 1:0] mem_strb_o;
	output mem_we_o;
	output [DataWidth - 1:0] mem_rdata_o;
	wire mem_gnt;
	ariane_mem_top i_ariane_mem_top(
		.clk_i(clk_i),
		.rst_ni(rst_ni),
		.mem_req_o(mem_req_o),
		.mem_gnt_i(mem_gnt),
		.mem_addr_o(mem_addr_o),
		.mem_wdata_o(mem_wdata_o),
		.mem_strb_o(mem_strb_o),
		.mem_we_o(mem_we_o),
		.mem_rdata_i(mem_rdata_o),
		.boot_addr_i(64'h0000000080000000),
		.hart_id_i(1'sb0),
		.irq_i(1'sb0),
		.ipi_i(1'sb0),
		.time_irq_i(1'sb0),
		.debug_req_i(1'sb0)
	);
	sram_mem #(
		.Width(DataWidth),
		.Depth(NumWords),
		.RelocateRequestUp(64'h0000000010000000)
	) i_sram(
		.clk_i(clk_i),
		.rst_ni(rst_ni),
		.req_i(mem_req_o),
		.write_i(mem_we_o),
		.addr_i(mem_addr_o >> 3),
		.wdata_i(mem_wdata_o),
		.wmask_i({{8 {mem_strb_o[7]}}, {8 {mem_strb_o[6]}}, {8 {mem_strb_o[5]}}, {8 {mem_strb_o[4]}}, {8 {mem_strb_o[3]}}, {8 {mem_strb_o[2]}}, {8 {mem_strb_o[1]}}, {8 {mem_strb_o[0]}}}),
		.rdata_o(mem_rdata_o)
	);
	assign mem_gnt = 1'b1;
endmodule


module tc_sram (
	clk_i,
	rst_ni,
	req_i,
	we_i,
	addr_i,
	wdata_i,
	be_i,
	rdata_o
);
	parameter [31:0] NumWords = 32'd1024;
	parameter [31:0] DataWidth = 32'd128;
	parameter [31:0] ByteWidth = 32'd8;
	parameter [31:0] NumPorts = 32'd2;
	parameter [31:0] Latency = 32'd1;
	parameter SimInit = "none";
	parameter [0:0] PrintSimCfg = 1'b0;
	parameter ImplKey = "none";
	parameter [31:0] AddrWidth = (NumWords > 32'd1 ? $clog2(NumWords) : 32'd1);
	parameter [31:0] BeWidth = ((DataWidth + ByteWidth) - 32'd1) / ByteWidth;
	input clk_i;
	input rst_ni;
	input [NumPorts - 1:0] req_i;
	input [NumPorts - 1:0] we_i;
	input [(NumPorts * AddrWidth) - 1:0] addr_i;
	input [(NumPorts * DataWidth) - 1:0] wdata_i;
	input [(NumPorts * BeWidth) - 1:0] be_i;
	output reg [(NumPorts * DataWidth) - 1:0] rdata_o;
	reg [(NumWords * DataWidth) - 1:0] sram;
	reg [(NumPorts * AddrWidth) - 1:0] r_addr_q;
	reg [(NumWords * DataWidth) - 1:0] init_val;
	initial begin : proc_sram_init
		begin : sv2v_autoblock_1
			reg [31:0] i;
			for (i = 0; i < NumWords; i = i + 1)
				case (SimInit)
					"zeros": init_val[i * DataWidth+:DataWidth] = {DataWidth {1'b0}};
					"ones": init_val[i * DataWidth+:DataWidth] = {DataWidth {1'b1}};
					"random": init_val[i * DataWidth+:DataWidth] = {DataWidth {$urandom()}};
					default: init_val[i * DataWidth+:DataWidth] = {DataWidth {1'bx}};
				endcase
		end
	end
	reg [((NumPorts * Latency) * DataWidth) - 1:0] rdata_q;
	reg [((NumPorts * Latency) * DataWidth) - 1:0] rdata_d;
	generate
		if (Latency == 32'd0) begin : gen_no_read_lat
			genvar i;
			for (i = 0; i < NumPorts; i = i + 1) begin : gen_port
				wire [DataWidth * 1:1] sv2v_tmp_03559;
				assign sv2v_tmp_03559 = (req_i[i] && !we_i[i] ? sram[addr_i[i * AddrWidth+:AddrWidth] * DataWidth+:DataWidth] : sram[r_addr_q[i * AddrWidth+:AddrWidth] * DataWidth+:DataWidth]);
				always @(*) rdata_o[i * DataWidth+:DataWidth] = sv2v_tmp_03559;
			end
		end
		else begin : gen_read_lat
			always @(*) begin : sv2v_autoblock_2
				reg [31:0] i;
				for (i = 0; i < NumPorts; i = i + 1)
					begin
						rdata_o[i * DataWidth+:DataWidth] = rdata_q[(i * Latency) * DataWidth+:DataWidth];
						begin : sv2v_autoblock_3
							reg [31:0] j;
							for (j = 0; j < (Latency - 1); j = j + 1)
								rdata_d[((i * Latency) + j) * DataWidth+:DataWidth] = rdata_q[((i * Latency) + (j + 1)) * DataWidth+:DataWidth];
						end
						rdata_d[((i * Latency) + (Latency - 1)) * DataWidth+:DataWidth] = (req_i[i] && !we_i[i] ? sram[addr_i[i * AddrWidth+:AddrWidth] * DataWidth+:DataWidth] : sram[r_addr_q[i * AddrWidth+:AddrWidth] * DataWidth+:DataWidth]);
					end
			end
		end
		if (SimInit == "none") begin : genblk2
			always @(posedge clk_i or negedge rst_ni)
				if (!rst_ni) begin : sv2v_autoblock_4
					reg signed [31:0] i;
					for (i = 0; i < NumPorts; i = i + 1)
						r_addr_q[i * AddrWidth+:AddrWidth] <= {AddrWidth {1'b0}};
				end
				else begin
					begin : sv2v_autoblock_5
						reg [31:0] i;
						for (i = 0; i < NumPorts; i = i + 1)
							if (Latency != 0) begin : sv2v_autoblock_6
								reg [31:0] j;
								for (j = 0; j < Latency; j = j + 1)
									rdata_q[((i * Latency) + j) * DataWidth+:DataWidth] <= rdata_d[((i * Latency) + j) * DataWidth+:DataWidth];
							end
					end
					begin : sv2v_autoblock_7
						reg [31:0] i;
						for (i = 0; i < NumPorts; i = i + 1)
							if (req_i[i]) begin
								if (we_i[i]) begin : sv2v_autoblock_8
									reg [31:0] j;
									for (j = 0; j < BeWidth; j = j + 1)
										if (be_i[(i * BeWidth) + j])
											sram[(addr_i[i * AddrWidth+:AddrWidth] * DataWidth) + (j * ByteWidth)+:ByteWidth] <= wdata_i[(i * DataWidth) + (j * ByteWidth)+:ByteWidth];
								end
								else
									r_addr_q[i * AddrWidth+:AddrWidth] <= addr_i[i * AddrWidth+:AddrWidth];
							end
					end
				end
		end
		else begin : genblk2
			always @(posedge clk_i or negedge rst_ni)
				if (!rst_ni) begin
					sram <= init_val;
					begin : sv2v_autoblock_9
						reg signed [31:0] i;
						for (i = 0; i < NumPorts; i = i + 1)
							begin
								r_addr_q[i * AddrWidth+:AddrWidth] <= {AddrWidth {1'b0}};
								if (Latency != 32'd0) begin : sv2v_autoblock_10
									reg [31:0] j;
									for (j = 0; j < Latency; j = j + 1)
										rdata_q[((i * Latency) + j) * DataWidth+:DataWidth] <= init_val[{AddrWidth {1'b0}} * DataWidth+:DataWidth];
								end
							end
					end
				end
				else begin
					begin : sv2v_autoblock_11
						reg [31:0] i;
						for (i = 0; i < NumPorts; i = i + 1)
							if (Latency != 0) begin : sv2v_autoblock_12
								reg [31:0] j;
								for (j = 0; j < Latency; j = j + 1)
									rdata_q[((i * Latency) + j) * DataWidth+:DataWidth] <= rdata_d[((i * Latency) + j) * DataWidth+:DataWidth];
							end
					end
					begin : sv2v_autoblock_13
						reg [31:0] i;
						for (i = 0; i < NumPorts; i = i + 1)
							if (req_i[i]) begin
								if (we_i[i]) begin : sv2v_autoblock_14
									reg [31:0] j;
									for (j = 0; j < BeWidth; j = j + 1)
										if (be_i[(i * BeWidth) + j])
											sram[(addr_i[i * AddrWidth+:AddrWidth] * DataWidth) + (j * ByteWidth)+:ByteWidth] <= wdata_i[(i * DataWidth) + (j * ByteWidth)+:ByteWidth];
								end
								else
									r_addr_q[i * AddrWidth+:AddrWidth] <= addr_i[i * AddrWidth+:AddrWidth];
							end
					end
				end
		end
	endgenerate
endmodule
module tc_sram_impl (
	clk_i,
	rst_ni,
	impl_i,
	impl_o,
	req_i,
	we_i,
	addr_i,
	wdata_i,
	be_i,
	rdata_o
);
	parameter [31:0] NumWords = 32'd1024;
	parameter [31:0] DataWidth = 32'd128;
	parameter [31:0] ByteWidth = 32'd8;
	parameter [31:0] NumPorts = 32'd2;
	parameter [31:0] Latency = 32'd1;
	parameter SimInit = "none";
	parameter [0:0] PrintSimCfg = 1'b0;
	parameter ImplKey = "none";
	parameter [0:0] ImplOutSim = 1'sbx;
	parameter [31:0] AddrWidth = (NumWords > 32'd1 ? $clog2(NumWords) : 32'd1);
	parameter [31:0] BeWidth = ((DataWidth + ByteWidth) - 32'd1) / ByteWidth;
	input clk_i;
	input rst_ni;
	input impl_i;
	output impl_o;
	input [NumPorts - 1:0] req_i;
	input [NumPorts - 1:0] we_i;
	input [(NumPorts * AddrWidth) - 1:0] addr_i;
	input [(NumPorts * DataWidth) - 1:0] wdata_i;
	input [(NumPorts * BeWidth) - 1:0] be_i;
	output [(NumPorts * DataWidth) - 1:0] rdata_o;
	assign impl_o = ImplOutSim;
	tc_sram #(
		.NumWords(NumWords),
		.DataWidth(DataWidth),
		.ByteWidth(ByteWidth),
		.NumPorts(NumPorts),
		.Latency(Latency),
		.SimInit(SimInit),
		.PrintSimCfg(PrintSimCfg),
		.ImplKey(ImplKey)
	) i_tc_sram(
		.clk_i(clk_i),
		.rst_ni(rst_ni),
		.req_i(req_i),
		.we_i(we_i),
		.addr_i(addr_i),
		.wdata_i(wdata_i),
		.be_i(be_i),
		.rdata_o(rdata_o)
	);
endmodule
module tc_clk_and2 (
	clk0_i,
	clk1_i,
	clk_o
);
	input clk0_i;
	input clk1_i;
	output clk_o;
	assign clk_o = clk0_i & clk1_i;
endmodule
module tc_clk_buffer (
	clk_i,
	clk_o
);
	input clk_i;
	output clk_o;
	assign clk_o = clk_i;
endmodule
module tc_clk_gating (
	clk_i,
	en_i,
	test_en_i,
	clk_o
);
	parameter [0:0] IS_FUNCTIONAL = 1'b1;
	input clk_i;
	input en_i;
	input test_en_i;
	output clk_o;
	reg clk_en;
	always @(*)
		if (clk_i == 1'b0)
			clk_en <= en_i | test_en_i;
	assign clk_o = clk_i & clk_en;
endmodule
module tc_clk_inverter (
	clk_i,
	clk_o
);
	input clk_i;
	output clk_o;
	assign clk_o = ~clk_i;
endmodule
module tc_clk_mux2 (
	clk0_i,
	clk1_i,
	clk_sel_i,
	clk_o
);
	input clk0_i;
	input clk1_i;
	input clk_sel_i;
	output clk_o;
	assign clk_o = (clk_sel_i ? clk1_i : clk0_i);
endmodule
module tc_clk_xor2 (
	clk0_i,
	clk1_i,
	clk_o
);
	input clk0_i;
	input clk1_i;
	output clk_o;
	assign clk_o = clk0_i ^ clk1_i;
endmodule
module tc_clk_or2 (
