module generic_memory (
	CLK,
	INITN,
	CEN,
	A,
	WEN,
	D,
	BEN,
	Q
);
	parameter ADDR_WIDTH = 12;
	parameter DATA_WIDTH = 32;
	parameter BE_WIDTH = DATA_WIDTH / 8;
	input CLK;
	input INITN;
	input CEN;
	input [ADDR_WIDTH - 1:0] A;
	input WEN;
	input [DATA_WIDTH - 1:0] D;
	input [BE_WIDTH - 1:0] BEN;
	output reg [DATA_WIDTH - 1:0] Q;
	parameter NUM_WORDS = 2 ** ADDR_WIDTH;
	reg [DATA_WIDTH - 1:0] MEM [NUM_WORDS - 1:0];
	wire [DATA_WIDTH - 1:0] M;
	genvar i;
	genvar j;
	generate
		for (i = 0; i < BE_WIDTH; i = i + 1) begin : genblk1
			for (j = 0; j < 8; j = j + 1) begin : genblk1
				assign M[(i * 8) + j] = BEN[i];
			end
		end
		for (i = 0; i < DATA_WIDTH; i = i + 1) begin : genblk2
			always @(posedge CLK)
				if (INITN == 1'b1) begin
					if (CEN == 1'b0) begin
						if (WEN == 1'b0) begin
							if (M[i] == 1'b0)
								MEM[A][i] <= D[i];
						end
						else if (WEN == 1'b1)
							Q[i] <= MEM[A][i];
					end
				end
		end
	endgenerate
endmodule
module generic_rom (
	CLK,
	CEN,
	A,
	Q
);
	parameter ADDR_WIDTH = 32;
	parameter DATA_WIDTH = 32;
	parameter FILE_NAME = "./boot/boot_code.cde";
	input CLK;
	input CEN;
	input [ADDR_WIDTH - 1:0] A;
	output [DATA_WIDTH - 1:0] Q;
	parameter NUM_WORDS = 2 ** ADDR_WIDTH;
	reg [DATA_WIDTH - 1:0] MEM [NUM_WORDS - 1:0];
	reg [ADDR_WIDTH - 1:0] A_Q;
	initial $readmemb(FILE_NAME, MEM);
	always @(posedge CLK)
		if (CEN == 1'b0)
			A_Q <= A;
	assign Q = MEM[A_Q];
endmodule
