module mv_filter (
	clk_i,
	rst_ni,
	sample_i,
	clear_i,
	d_i,
	q_o
);
	parameter [31:0] WIDTH = 4;
	parameter [31:0] THRESHOLD = 10;
	input clk_i;
	input rst_ni;
	input sample_i;
	input clear_i;
	input d_i;
	output q_o;
	reg [WIDTH - 1:0] counter_q;
	reg [WIDTH - 1:0] counter_d;
	reg d;
	reg q;
	assign q_o = q;
	always @(*) begin
		counter_d = counter_q;
		d = q;
		if (counter_q >= THRESHOLD[WIDTH - 1:0])
			d = 1'b1;
		else if (sample_i && d_i)
			counter_d = counter_q + 1;
		if (clear_i) begin
			counter_d = 1'sb0;
			d = 1'b0;
		end
	end
	always @(posedge clk_i or negedge rst_ni)
		if (~rst_ni) begin
			counter_q <= 1'sb0;
			q <= 1'b0;
		end
		else begin
			counter_q <= counter_d;
			q <= d;
		end
endmodule
module onehot_to_bin (
	onehot,
	bin
);
	parameter [31:0] ONEHOT_WIDTH = 16;
	parameter [31:0] BIN_WIDTH = (ONEHOT_WIDTH == 1 ? 1 : $clog2(ONEHOT_WIDTH));
	input [ONEHOT_WIDTH - 1:0] onehot;
	output [BIN_WIDTH - 1:0] bin;
	genvar j;
	generate
		for (j = 0; j < BIN_WIDTH; j = j + 1) begin : gen_jl
			wire [ONEHOT_WIDTH - 1:0] tmp_mask;
			genvar i;
			for (i = 0; i < ONEHOT_WIDTH; i = i + 1) begin : gen_il
				wire [BIN_WIDTH - 1:0] tmp_i;
				assign tmp_i = i;
				assign tmp_mask[i] = tmp_i[j];
			end
			assign bin[j] = |(tmp_mask & onehot);
		end
	endgenerate
endmodule
module plru_tree (
	clk_i,
	rst_ni,
	used_i,
	plru_o
