	parameter [31:0] ENTRIES = 16;
	input clk_i;
	input rst_ni;
	input [ENTRIES - 1:0] used_i;
	output reg [ENTRIES - 1:0] plru_o;
	parameter [31:0] LogEntries = $clog2(ENTRIES);
