module stream_demux (
	inp_valid_i,
	inp_ready_o,
	oup_sel_i,
	oup_valid_o,
	oup_ready_i
);
	parameter [31:0] N_OUP = 32'd1;
	parameter [31:0] LOG_N_OUP = (N_OUP > 32'd1 ? $unsigned($clog2(N_OUP)) : 1'b1);
	input inp_valid_i;
	output inp_ready_o;
	input [LOG_N_OUP - 1:0] oup_sel_i;
	output reg [N_OUP - 1:0] oup_valid_o;
	input [N_OUP - 1:0] oup_ready_i;
	always @(*) begin
		oup_valid_o = 1'sb0;
		oup_valid_o[oup_sel_i] = inp_valid_i;
	end
	assign inp_ready_o = oup_ready_i[oup_sel_i];
endmodule
module stream_filter (
	valid_i,
	ready_o,
	drop_i,
	valid_o,
	ready_i
);
	input valid_i;
	output ready_o;
	input drop_i;
	output valid_o;
	input ready_i;
	assign valid_o = (drop_i ? 1'b0 : valid_i);
	assign ready_o = (drop_i ? 1'b1 : ready_i);
endmodule
module stream_fork (
	clk_i,
	rst_ni,
	valid_i,
	ready_o,
	valid_o,
	ready_i
);
	parameter [31:0] N_OUP = 0;
	input clk_i;
	input rst_ni;
	input valid_i;
	output reg ready_o;
	output reg [N_OUP - 1:0] valid_o;
	input [N_OUP - 1:0] ready_i;
	reg [N_OUP - 1:0] oup_ready;
	wire [N_OUP - 1:0] all_ones;
	reg inp_state_d;
	reg inp_state_q;
	always @(*) begin
		inp_state_d = inp_state_q;
		case (inp_state_q)
			1'd0:
				if (valid_i) begin
					if ((valid_o == all_ones) && (ready_i == all_ones))
						ready_o = 1'b1;
					else begin
						ready_o = 1'b0;
						inp_state_d = 1'd1;
					end
				end
				else
					ready_o = 1'b0;
			1'd1:
				if (valid_i && (oup_ready == all_ones)) begin
					ready_o = 1'b1;
					inp_state_d = 1'd0;
				end
				else
					ready_o = 1'b0;
			default: begin
				inp_state_d = 1'd0;
				ready_o = 1'b0;
			end
		endcase
	end
	always @(posedge clk_i or negedge rst_ni)
		if (!rst_ni)
			inp_state_q <= 1'd0;
		else
			inp_state_q <= inp_state_d;
	genvar i;
	generate
		for (i = 0; i < N_OUP; i = i + 1) begin : gen_oup_state
			reg oup_state_d;
			reg oup_state_q;
			always @(*) begin
				oup_ready[i] = 1'b1;
				valid_o[i] = 1'b0;
				oup_state_d = oup_state_q;
				case (oup_state_q)
					1'd0:
						if (valid_i) begin
							valid_o[i] = 1'b1;
							if (ready_i[i]) begin
								if (!ready_o)
									oup_state_d = 1'd1;
							end
							else
								oup_ready[i] = 1'b0;
						end
					1'd1:
						if (valid_i && ready_o)
							oup_state_d = 1'd0;
					default: oup_state_d = 1'd0;
				endcase
			end
			always @(posedge clk_i or negedge rst_ni)
				if (!rst_ni)
					oup_state_q <= 1'd0;
				else
					oup_state_q <= oup_state_d;
		end
	endgenerate
	assign all_ones = 1'sb1;
endmodule
module stream_join (
	inp_valid_i,
	inp_ready_o,
	oup_valid_o,
	oup_ready_i
);
	parameter [31:0] N_INP = 32'd0;
	input [N_INP - 1:0] inp_valid_i;
	output [N_INP - 1:0] inp_ready_o;
	output oup_valid_o;
	input oup_ready_i;
	assign oup_valid_o = &inp_valid_i;
	genvar i;
	generate
		for (i = 0; i < N_INP; i = i + 1) begin : gen_inp_ready
			assign inp_ready_o[i] = oup_valid_o & oup_ready_i;
		end
	endgenerate
endmodule
module stream_mux (
	inp_data_i,
	inp_valid_i,
	inp_ready_o,
	inp_sel_i,
	oup_data_o,
	oup_valid_o,
	oup_ready_i
);
	parameter integer N_INP = 0;
	parameter integer LOG_N_INP = $clog2(N_INP);
	input [N_INP - 1:0] inp_data_i;
	input [N_INP - 1:0] inp_valid_i;
	output reg [N_INP - 1:0] inp_ready_o;
	input [LOG_N_INP - 1:0] inp_sel_i;
	output oup_data_o;
	output oup_valid_o;
	input oup_ready_i;
	always @(*) begin
		inp_ready_o = 1'sb0;
		inp_ready_o[inp_sel_i] = oup_ready_i;
	end
	assign oup_data_o = inp_data_i[inp_sel_i];
	assign oup_valid_o = inp_valid_i[inp_sel_i];
endmodule
module stream_throttle (
	clk_i,
	rst_ni,
	req_valid_i,
	req_valid_o,
	req_ready_i,
	req_ready_o,
	rsp_valid_i,
	rsp_ready_i,
	credit_i
);
	parameter [31:0] MaxNumPending = 1;
	function automatic [31:0] cf_math_pkg_idx_width;
		input reg [31:0] num_idx;
		cf_math_pkg_idx_width = (num_idx > 32'd1 ? $unsigned($clog2(num_idx)) : 32'd1);
	endfunction
	parameter [31:0] CntWidth = cf_math_pkg_idx_width(MaxNumPending);
	input clk_i;
	input rst_ni;
	input req_valid_i;
	output req_valid_o;
	input req_ready_i;
	output req_ready_o;
	input rsp_valid_i;
	input rsp_ready_i;
	input [CntWidth - 1:0] credit_i;
	reg [CntWidth - 1:0] credit_d;
	reg [CntWidth - 1:0] credit_q;
	wire credit_available;
	always @(*) begin : proc_credit_counter
		credit_d = credit_q;
		if (req_ready_o & req_valid_o)
			credit_d = credit_d + 'd1;
		if (rsp_valid_i & rsp_ready_i)
			credit_d = credit_d - 'd1;
	end
	assign credit_available = credit_q <= (credit_i - 'd1);
	assign req_valid_o = req_valid_i & credit_available;
	assign req_ready_o = req_ready_i & credit_available;
	always @(posedge clk_i or negedge rst_ni)
		if (!rst_ni)
			credit_q <= 1'sb0;
		else
			credit_q <= credit_d;
endmodule
module lossy_valid_to_stream (
	clk_i,
	rst_ni,
	valid_i,
	data_i,
	valid_o,
	ready_i,
	data_o,
	busy_o
);
	parameter [31:0] DATA_WIDTH = 32;
	input clk_i;
	input rst_ni;
	input valid_i;
	input [DATA_WIDTH - 1:0] data_i;
	output valid_o;
	input ready_i;
	output reg [DATA_WIDTH - 1:0] data_o;
	output busy_o;
	reg read_ptr_d;
	reg read_ptr_q;
	reg write_ptr_d;
	reg write_ptr_q;
	reg [1:0] pending_tx_counter_d;
	reg [1:0] pending_tx_counter_q;
	reg [(2 * DATA_WIDTH) - 1:0] mem_d;
	reg [(2 * DATA_WIDTH) - 1:0] mem_q;
	assign valid_o = (pending_tx_counter_q != 0) || valid_i;
	always @(*) begin : write_logic
		write_ptr_d = write_ptr_q;
		mem_d = mem_q;
		if (valid_i) begin
			if ((pending_tx_counter_q != 0) || !ready_i) begin
				if ((pending_tx_counter_q == 2) && !ready_i)
					mem_d[(write_ptr_q - 1'b1) * DATA_WIDTH+:DATA_WIDTH] = data_i;
				else begin
					mem_d[write_ptr_q * DATA_WIDTH+:DATA_WIDTH] = data_i;
					write_ptr_d = write_ptr_q + 1'b1;
				end
			end
		end
	end
	always @(*) begin : read_logic
		read_ptr_d = read_ptr_q;
		data_o = mem_q[read_ptr_q * DATA_WIDTH+:DATA_WIDTH];
		if ((pending_tx_counter_q == 0) && valid_i)
			data_o = data_i;
		else if (valid_o && ready_i)
			read_ptr_d = read_ptr_q + 1'b1;
	end
	always @(*) begin : count_transactions
		pending_tx_counter_d = pending_tx_counter_q;
		if ((valid_i && valid_o) && ready_i)
			pending_tx_counter_d = pending_tx_counter_q;
		else if (valid_i && !(valid_o && ready_i)) begin
			if (pending_tx_counter_q != 2)
				pending_tx_counter_d = pending_tx_counter_q + 1'b1;
		end
		else if (!valid_i && (valid_o && ready_i))
			pending_tx_counter_d = pending_tx_counter_q - 1'b1;
	end
	always @(posedge clk_i or negedge rst_ni)
		if (!rst_ni) begin
			read_ptr_q <= 1'sb0;
			write_ptr_q <= 1'sb0;
			pending_tx_counter_q <= 1'sb0;
			mem_q <= 1'sb0;
		end
		else begin
			read_ptr_q <= read_ptr_d;
			write_ptr_q <= write_ptr_d;
			pending_tx_counter_q <= pending_tx_counter_d;
			mem_q <= mem_d;
		end
	assign busy_o = pending_tx_counter_q != 0;
endmodule
module sub_per_hash (
	data_i,
	hash_o,
	hash_onehot_o
);
	parameter [31:0] InpWidth = 32'd11;
	parameter [31:0] HashWidth = 32'd5;
	parameter [31:0] NoRounds = 32'd1;
	parameter [31:0] PermuteKey = 32'd299034753;
	parameter [31:0] XorKey = 32'd4094834;
	input [InpWidth - 1:0] data_i;
	output [HashWidth - 1:0] hash_o;
	output [(2 ** HashWidth) - 1:0] hash_onehot_o;
	wire [((NoRounds * InpWidth) * 32) - 1:0] Permutations;
	function automatic [((NoRounds * InpWidth) * 32) - 1:0] get_permutations;
		input reg [31:0] seed;
		reg [31:0] indices [0:NoRounds - 1][0:InpWidth - 1];
		reg [((NoRounds * InpWidth) * 32) - 1:0] perm_array;
		reg [63:0] A;
		reg [63:0] C;
		reg [63:0] M;
		reg [63:0] index;
		reg [63:0] advance;
		reg [63:0] rand_number;
		begin
			A = 2147483629;
			C = 2147483587;
			M = 33'sd2147483648 - 1;
			index = 0;
			advance = 0;
			rand_number = ((A * seed) + C) % M;
			begin : sv2v_autoblock_1
				reg [31:0] r;
				for (r = 0; r < NoRounds; r = r + 1)
					begin
						begin : sv2v_autoblock_2
							reg [31:0] i;
							for (i = 0; i < InpWidth; i = i + 1)
								indices[r][i] = i;
						end
						begin : sv2v_autoblock_3
							reg [31:0] i;
							for (i = 0; i < InpWidth; i = i + 1)
								begin
									if (i > 0) begin
										rand_number = ((A * rand_number) + C) % M;
										index = rand_number % i;
									end
									if (i != index) begin
										perm_array[((((NoRounds - 1) - r) * InpWidth) + ((InpWidth - 1) - i)) * 32+:32] = perm_array[((((NoRounds - 1) - r) * InpWidth) + ((InpWidth - 1) - index)) * 32+:32];
										perm_array[((((NoRounds - 1) - r) * InpWidth) + ((InpWidth - 1) - index)) * 32+:32] = indices[r][i];
									end
								end
						end
						rand_number = ((A * rand_number) + C) % M;
						advance = rand_number % NoRounds;
						begin : sv2v_autoblock_4
							reg [31:0] i;
							for (i = 0; i < advance; i = i + 1)
								rand_number = ((A * rand_number) + C) % M;
						end
					end
			end
			get_permutations = perm_array;
		end
	endfunction
	assign Permutations = get_permutations(PermuteKey);
	wire [(((NoRounds * InpWidth) * 3) * 32) - 1:0] XorStages;
	function automatic [(((NoRounds * InpWidth) * 3) * 32) - 1:0] get_xor_stages;
		input reg [31:0] seed;
		reg [(((NoRounds * InpWidth) * 3) * 32) - 1:0] xor_array;
		reg [63:0] A;
		reg [63:0] C;
		reg [63:0] M;
		reg [63:0] index;
		reg [63:0] advance;
		reg [63:0] rand_number;
		begin
			A = 1664525;
			C = 1013904223;
			M = 34'sd4294967296;
			index = 0;
			advance = 0;
			rand_number = ((A * seed) + C) % M;
			begin : sv2v_autoblock_5
				reg [31:0] r;
				for (r = 0; r < NoRounds; r = r + 1)
					begin
						begin : sv2v_autoblock_6
							reg [31:0] i;
							for (i = 0; i < InpWidth; i = i + 1)
								begin
									rand_number = ((A * rand_number) + C) % M;
									begin : sv2v_autoblock_7
										reg [31:0] j;
										for (j = 0; j < 3; j = j + 1)
											begin
												rand_number = ((A * rand_number) + C) % M;
												index = rand_number % InpWidth;
												xor_array[((((((NoRounds - 1) - r) * InpWidth) + ((InpWidth - 1) - i)) * 3) + (2 - j)) * 32+:32] = index;
											end
									end
								end
						end
						rand_number = ((A * rand_number) + C) % M;
						advance = rand_number % NoRounds;
						begin : sv2v_autoblock_8
							reg [31:0] i;
							for (i = 0; i < advance; i = i + 1)
								rand_number = ((A * rand_number) + C) % M;
						end
					end
			end
			get_xor_stages = xor_array;
		end
	endfunction
	assign XorStages = get_xor_stages(XorKey);
	wire [(NoRounds * InpWidth) - 1:0] permuted;
	wire [(NoRounds * InpWidth) - 1:0] xored;
	genvar r;
	generate
		for (r = 0; r < NoRounds; r = r + 1) begin : gen_round
			genvar i;
			for (i = 0; i < InpWidth; i = i + 1) begin : gen_sub_per
				if (r == 0) begin : gen_input
					assign permuted[(r * InpWidth) + i] = data_i[Permutations[((((NoRounds - 1) - r) * InpWidth) + ((InpWidth - 1) - i)) * 32+:32]];
				end
				else begin : gen_permutation
					assign permuted[(r * InpWidth) + i] = permuted[((r - 1) * InpWidth) + Permutations[((((NoRounds - 1) - r) * InpWidth) + ((InpWidth - 1) - i)) * 32+:32]];
				end
				assign xored[(r * InpWidth) + i] = (permuted[(r * InpWidth) + XorStages[((((((NoRounds - 1) - r) * InpWidth) + ((InpWidth - 1) - i)) * 3) + 2) * 32+:32]] ^ permuted[(r * InpWidth) + XorStages[((((((NoRounds - 1) - r) * InpWidth) + ((InpWidth - 1) - i)) * 3) + 1) * 32+:32]]) ^ permuted[(r * InpWidth) + XorStages[(((((NoRounds - 1) - r) * InpWidth) + ((InpWidth - 1) - i)) * 3) * 32+:32]];
			end
		end
	endgenerate
	assign hash_o = xored[((NoRounds - 1) * InpWidth) + (HashWidth - 1)-:HashWidth];
	assign hash_onehot_o = 1 << hash_o;
endmodule
module sync (
	clk_i,
	rst_ni,
	serial_i,
	serial_o
);
	parameter [31:0] STAGES = 2;
	parameter [0:0] ResetValue = 1'b0;
	input clk_i;
	input rst_ni;
	input serial_i;
	output serial_o;
	reg [STAGES - 1:0] reg_q;
	always @(posedge clk_i or negedge rst_ni)
		if (!rst_ni)
