	input dst_rst_ni;
	input dst_clk_i;
	output dst_data_o;
	output dst_valid_o;
	input dst_ready_i;
	parameter signed [31:0] PtrWidth = LOG_DEPTH + 1;
	parameter [PtrWidth - 1:0] PtrFull = 1 << LOG_DEPTH;
	parameter [PtrWidth - 1:0] PtrEmpty = 1'sb0;
