		if (!src_rst_ni)
			src_wptr_q <= 0;
		else if (src_valid_i && src_ready_o)
			src_wptr_q <= src_wptr_q + 1;
	always @(posedge dst_clk_i or negedge dst_rst_ni)
		if (!dst_rst_ni)
			dst_rptr_q <= 0;
		else if (dst_valid_o && dst_ready_i)
			dst_rptr_q <= dst_rptr_q + 1;
