	assign push = valid_i & ~full;
	assign pop = ready_i & ~empty;
	assign ready_o = ~full;
	assign valid_o = ~empty;
	fifo_v3_CE4E5 #(
		.FALL_THROUGH(FALL_THROUGH),
		.DATA_WIDTH(DATA_WIDTH),
		.DEPTH(DEPTH)
	) fifo_i(
		.clk_i(clk_i),
		.rst_ni(rst_ni),
		.flush_i(flush_i),
		.testmode_i(testmode_i),
		.full_o(full),
		.empty_o(empty),
		.usage_o(usage_o),
		.data_i(data_i),
		.push_i(push),
		.data_o(data_o),
		.pop_i(pop)
	);
endmodule
module stream_fork_dynamic (
	clk_i,
	rst_ni,
	valid_i,
	ready_o,
	sel_i,
	sel_valid_i,
	sel_ready_o,
	valid_o,
	ready_i
);
	parameter [31:0] N_OUP = 32'd0;
	input clk_i;
	input rst_ni;
	input valid_i;
	output reg ready_o;
	input [N_OUP - 1:0] sel_i;
	input sel_valid_i;
	output reg sel_ready_o;
	output reg [N_OUP - 1:0] valid_o;
	input [N_OUP - 1:0] ready_i;
	reg int_inp_valid;
	wire int_inp_ready;
	wire [N_OUP - 1:0] int_oup_valid;
	reg [N_OUP - 1:0] int_oup_ready;
	genvar i;
	generate
		for (i = 0; i < N_OUP; i = i + 1) begin : gen_oups
			always @(*) begin
				valid_o[i] = 1'b0;
				int_oup_ready[i] = 1'b0;
				if (sel_valid_i) begin
					if (sel_i[i]) begin
						valid_o[i] = int_oup_valid[i];
						int_oup_ready[i] = ready_i[i];
					end
					else
						int_oup_ready[i] = 1'b1;
				end
			end
		end
	endgenerate
	always @(*) begin
		int_inp_valid = 1'b0;
		ready_o = 1'b0;
		sel_ready_o = 1'b0;
		if (sel_valid_i) begin
			int_inp_valid = valid_i;
			ready_o = int_inp_ready;
			sel_ready_o = int_inp_ready;
		end
	end
	stream_fork #(.N_OUP(N_OUP)) i_fork(
		.clk_i(clk_i),
		.rst_ni(rst_ni),
		.valid_i(int_inp_valid),
		.ready_o(int_inp_ready),
		.valid_o(int_oup_valid),
		.ready_i(int_oup_ready)
	);
endmodule
module clk_mux_glitch_free (
	clks_i,
	test_clk_i,
	test_en_i,
	async_rstn_i,
	async_sel_i,
	clk_o
);
	parameter [31:0] NUM_INPUTS = 2;
	parameter [31:0] NUM_SYNC_STAGES = 2;
	parameter [0:0] CLOCK_DURING_RESET = 1'b1;
	parameter [31:0] SelWidth = $clog2(NUM_INPUTS);
	input [NUM_INPUTS - 1:0] clks_i;
	input test_clk_i;
	input test_en_i;
	input async_rstn_i;
	input [SelWidth - 1:0] async_sel_i;
	output clk_o;
	generate
		if (NUM_INPUTS < 2) begin : genblk1
			$error("Num inputs must be parametrized to a value >= 2.");
		end
	endgenerate
	reg [NUM_INPUTS - 1:0] s_sel_onehot;
	wire [(NUM_INPUTS * 2) - 1:0] glitch_filter_d;
	reg [(NUM_INPUTS * 2) - 1:0] glitch_filter_q;
	reg [NUM_INPUTS - 1:0] s_gate_enable_unfiltered_async;
	wire [NUM_INPUTS - 1:0] s_glitch_filter_output_async;
	wire [NUM_INPUTS - 1:0] s_gate_enable_sync;
	wire [NUM_INPUTS - 1:0] s_gate_enable;
	reg [NUM_INPUTS - 1:0] clock_has_been_disabled_q;
	wire [NUM_INPUTS - 1:0] s_gated_clock;
	wire s_output_clock;
	wire [NUM_INPUTS - 1:0] s_reset_synced;
	reg [NUM_INPUTS - 1:0] async_reset_bypass_active_q;
	always @(*) begin
		s_sel_onehot = 1'sb0;
		s_sel_onehot[async_sel_i] = 1'b1;
	end
	genvar i;
	generate
		for (i = 0; i < NUM_INPUTS; i = i + 1) begin : gen_input_stages
			rstgen i_rstgen(
				.clk_i(clks_i[i]),
				.rst_ni(async_rstn_i),
				.test_mode_i(test_en_i),
				.rst_no(s_reset_synced[i]),
				.init_no()
			);
			always @(*) begin
				s_gate_enable_unfiltered_async[i] = 1'b1;
				begin : sv2v_autoblock_1
					reg signed [31:0] j;
					for (j = 0; j < NUM_INPUTS; j = j + 1)
						if (i == j)
							s_gate_enable_unfiltered_async[i] = s_gate_enable_unfiltered_async[i] & s_sel_onehot[j];
						else
							s_gate_enable_unfiltered_async[i] = s_gate_enable_unfiltered_async[i] & clock_has_been_disabled_q[j];
				end
			end
			assign glitch_filter_d[i * 2] = s_gate_enable_unfiltered_async[i];
			assign glitch_filter_d[(i * 2) + 1] = glitch_filter_q[i * 2];
			always @(posedge clks_i[i] or negedge s_reset_synced[i])
				if (!s_reset_synced[i])
					glitch_filter_q[i * 2+:2] <= 1'sb0;
				else
					glitch_filter_q[i * 2+:2] <= glitch_filter_d[i * 2+:2];
			assign s_glitch_filter_output_async[i] = (glitch_filter_q[(i * 2) + 1] & glitch_filter_q[i * 2]) & s_gate_enable_unfiltered_async[i];
			sync #(.STAGES(NUM_SYNC_STAGES)) i_sync_en(
				.clk_i(clks_i[i]),
				.rst_ni(s_reset_synced[i]),
				.serial_i(s_glitch_filter_output_async[i]),
				.serial_o(s_gate_enable_sync[i])
			);
			if (CLOCK_DURING_RESET) begin : gen_async_reset_clock_bypass_logic
				always @(posedge clks_i[i] or negedge s_reset_synced[i])
					if (!s_reset_synced[i])
						async_reset_bypass_active_q[i] <= 1'b1;
					else
						async_reset_bypass_active_q[i] <= 1'b0;
				assign s_gate_enable[i] = (async_reset_bypass_active_q[i] ? s_gate_enable_unfiltered_async[i] : s_gate_enable_sync[i]);
			end
			else begin : gen_no_async_reset_bypass_logic
				assign s_gate_enable[i] = s_gate_enable_sync[i];
			end
			tc_clk_gating #(.IS_FUNCTIONAL(1'b1)) i_clk_gate(
				.clk_i(clks_i[i]),
				.en_i(s_gate_enable[i]),
				.test_en_i(1'b0),
				.clk_o(s_gated_clock[i])
			);
			always @(posedge clks_i[i] or negedge s_reset_synced[i])
				if (!s_reset_synced[i])
					clock_has_been_disabled_q[i] <= 1'b1;
				else
					clock_has_been_disabled_q[i] <= ~s_gate_enable[i];
		end
	endgenerate
	clk_or_tree #(.NUM_INPUTS(NUM_INPUTS)) i_clk_or_tree(
		.clks_i(s_gated_clock),
		.clk_o(s_output_clock)
	);
	tc_clk_mux2 i_test_clk_mux(
		.clk0_i(s_output_clock),
		.clk1_i(test_clk_i),
		.clk_sel_i(test_en_i),
		.clk_o(clk_o)
	);
endmodule
module clk_or_tree (
	clks_i,
	clk_o
);
	parameter [31:0] NUM_INPUTS = 0;
	input [NUM_INPUTS - 1:0] clks_i;
	output clk_o;
	generate
		if (NUM_INPUTS < 1) begin : gen_error
			$error("Cannot parametrize clk_or with less then 1 input but was %0d", NUM_INPUTS);
		end
		else if (NUM_INPUTS == 1) begin : gen_leaf
			assign clk_o = clks_i[0];
		end
		else if (NUM_INPUTS == 2) begin : gen_leaf
			tc_clk_or2 i_clk_or2(
				.clk0_i(clks_i[0]),
				.clk1_i(clks_i[1]),
				.clk_o(clk_o)
			);
		end
		else begin : gen_recursive
			wire branch_a;
			wire branch_b;
			clk_or_tree #(.NUM_INPUTS(NUM_INPUTS / 2)) i_or_branch_a(
				.clks_i(clks_i[0+:NUM_INPUTS / 2]),
				.clk_o(branch_a)
			);
			clk_or_tree #(.NUM_INPUTS((NUM_INPUTS / 2) + (NUM_INPUTS % 2))) i_or_branch_b(
				.clks_i(clks_i[NUM_INPUTS - 1:NUM_INPUTS / 2]),
				.clk_o(branch_b)
			);
			tc_clk_or2 i_clk_or2(
				.clk0_i(branch_a),
				.clk1_i(branch_b),
				.clk_o(clk_o)
			);
		end
	endgenerate
endmodule
