	input clk_rx_i;
	input rstn_rx_i;
	output edge_o;
	reg [1:0] sync_a;
	wire sync_b;
	reg r_input_reg;
	wire s_input_reg_next;
	assign ack_tx_o = sync_a[0];
	assign s_input_reg_next = edge_i | (r_input_reg & ~sync_a[0]);
