	reg [(AxiMaxReads * AxiIdWidth) - 1:0] mst_ar_id;
	reg [AxiMaxReads - 1:0] mst_ar_valid_tran;
	wire [AxiMaxReads - 1:0] mst_ar_ready_tran;
	wire [TranIdWidth - 1:0] mst_req_idx;
	parameter [31:0] sv2v_uu_i_mst_ar_arb_NumIn = AxiMaxReads;
	parameter [31:0] sv2v_uu_i_mst_ar_arb_IdxWidth = (sv2v_uu_i_mst_ar_arb_NumIn > 32'd1 ? $unsigned($clog2(sv2v_uu_i_mst_ar_arb_NumIn)) : 32'd1);
	parameter [sv2v_uu_i_mst_ar_arb_IdxWidth - 1:0] sv2v_uu_i_mst_ar_arb_ext_rr_i_0 = 1'sb0;
	wire [$bits(type(mst_req.ar_valid)):1] sv2v_tmp_i_mst_ar_arb_req_o;
	always @(*) mst_req.ar_valid = sv2v_tmp_i_mst_ar_arb_req_o;
	wire [$bits(type(mst_req.ar)):1] sv2v_tmp_i_mst_ar_arb_data_o;
	always @(*) mst_req.ar = sv2v_tmp_i_mst_ar_arb_data_o;
	rr_arb_tree_25AF9 #(
		.NumIn(AxiMaxReads),
		.AxiVldRdy(1'b1),
		.ExtPrio(1'b0),
		.LockIn(1'b1)
	) i_mst_ar_arb(
		.clk_i(clk_i),
		.rst_ni(rst_ni),
		.flush_i(1'b0),
		.rr_i(sv2v_uu_i_mst_ar_arb_ext_rr_i_0),
		.req_i(mst_ar_valid_tran),
		.gnt_o(mst_ar_ready_tran),
		.data_i(mst_ar_tran),
		.gnt_i(mst_resp.ar_ready),
		.req_o(sv2v_tmp_i_mst_ar_arb_req_o),
		.data_o(sv2v_tmp_i_mst_ar_arb_data_o),
		.idx_o(mst_req_idx)
