	wire axi_err_req;
	wire axi_err_resp;
	parameter axi_pkg_RESP_SLVERR = 2'b10;
	axi_err_slv_29C08 #(
		.AxiIdWidth(AxiIdWidth),
		.Resp(axi_pkg_RESP_SLVERR)
	) i_axi_err_slv(
		.clk_i(clk_i),
