		.clk_i(clk_i),
		.rst_ni(rst_ni),
		.test_i(1'b0),
		.mst_reqs_o({axi_err_req, mst_req_o}),
		.mst_resps_i({axi_err_resp, mst_resp_i}),
		.slv_ar_select_i(mst_req_ar_err[mst_req_idx]),
		.slv_aw_select_i(mst_req_aw_err),
		.slv_req_i(mst_req),
		.slv_resp_o(mst_resp)
	);
	reg [15:0] w_req_d;
	reg [15:0] w_req_q;
	wire [AxiMaxReads - 1:0] idle_read_upsizer;
	wire [TranIdWidth - 1:0] idx_ar_upsizer;
	wire [TranIdWidth - 1:0] idx_idle_upsizer;
	lzc #(.WIDTH(AxiMaxReads)) i_idle_lzc(
		.in_i(idle_read_upsizer),
		.cnt_o(idx_idle_upsizer),
		.empty_o()
	);
	wire [AxiMaxReads - 1:0] id_clash_upsizer;
	wire [TranIdWidth - 1:0] idx_id_clash_upsizer;
	genvar t;
	generate
		for (t = 0; t < AxiMaxReads; t = t + 1) begin : gen_id_clash
			assign id_clash_upsizer[t] = (arb_slv_ar_id == mst_ar_id[t * AxiIdWidth+:AxiIdWidth]) && !idle_read_upsizer[t];
		end
	endgenerate
	onehot_to_bin #(.ONEHOT_WIDTH(AxiMaxReads)) i_id_clash_onehot_to_bin(
		.onehot(id_clash_upsizer),
		.bin(idx_id_clash_upsizer)
	);
	assign idx_ar_upsizer = (|id_clash_upsizer ? idx_id_clash_upsizer : idx_idle_upsizer);
	wire r_upsizer_valid;
	wire [TranIdWidth - 1:0] idx_r_upsizer;
	wire [AxiMaxReads - 1:0] rid_upsizer_match;
	assign r_upsizer_valid = |rid_upsizer_match;
	generate
		for (t = 0; t < AxiMaxReads; t = t + 1) begin : gen_rid_match
			assign rid_upsizer_match[t] = (mst_resp.r.id == mst_ar_id[t * AxiIdWidth+:AxiIdWidth]) && !idle_read_upsizer[t];
		end
	endgenerate
	onehot_to_bin #(.ONEHOT_WIDTH(AxiMaxReads)) i_rid_upsizer_lzc(
		.onehot(rid_upsizer_match),
		.bin(idx_r_upsizer)
	);
	parameter axi_pkg_BURST_FIXED = 2'b00;
	parameter axi_pkg_BURST_INCR = 2'b01;
	parameter axi_pkg_BURST_WRAP = 2'b10;
	function automatic [127:0] axi_pkg_aligned_addr;
		input reg [127:0] addr;
		input reg [2:0] size;
		axi_pkg_aligned_addr = (addr >> size) << size;
	endfunction
	function automatic [15:0] axi_pkg_num_bytes;
		input reg [2:0] size;
		axi_pkg_num_bytes = 1 << size;
	endfunction
	function automatic [127:0] axi_pkg_wrap_boundary;
		input reg [127:0] addr;
		input reg [2:0] size;
		input reg [7:0] len;
		reg [127:0] wrap_addr;
		begin
			case (len)
				4'b0001: wrap_addr = (addr >> ($unsigned(size) + 1)) << ($unsigned(size) + 1);
				4'b0011: wrap_addr = (addr >> ($unsigned(size) + 2)) << ($unsigned(size) + 2);
				4'b0111: wrap_addr = (addr >> ($unsigned(size) + 3)) << ($unsigned(size) + 3);
				4'b1111: wrap_addr = (addr >> ($unsigned(size) + 4)) << ($unsigned(size) + 4);
				default: wrap_addr = 1'sb0;
			endcase
			axi_pkg_wrap_boundary = wrap_addr;
		end
	endfunction
	function automatic [127:0] axi_pkg_beat_addr;
		input reg [127:0] addr;
		input reg [2:0] size;
		input reg [7:0] len;
		input reg [1:0] burst;
		input reg [15:0] i_beat;
		reg [127:0] ret_addr;
		reg [127:0] wrp_bond;
		begin
			ret_addr = addr;
			wrp_bond = 1'sb0;
			if (burst == axi_pkg_BURST_WRAP)
				wrp_bond = axi_pkg_wrap_boundary(addr, size, len);
			if ((i_beat != 0) && (burst != axi_pkg_BURST_FIXED)) begin
				ret_addr = axi_pkg_aligned_addr(addr, size) + (i_beat * axi_pkg_num_bytes(size));
				if ((burst == axi_pkg_BURST_WRAP) && (ret_addr >= (wrp_bond + (axi_pkg_num_bytes(size) * (len + 1)))))
					ret_addr = ret_addr - (axi_pkg_num_bytes(size) * (len + 1));
			end
			axi_pkg_beat_addr = ret_addr;
		end
	endfunction
	parameter axi_pkg_CACHE_MODIFIABLE = 4'b0010;
	function automatic axi_pkg_modifiable;
		input reg [3:0] cache;
		axi_pkg_modifiable = |(cache & axi_pkg_CACHE_MODIFIABLE);
	endfunction
	function automatic [31:0] cf_math_pkg_idx_width;
		input reg [31:0] num_idx;
		cf_math_pkg_idx_width = (num_idx > 32'd1 ? $unsigned($clog2(num_idx)) : 32'd1);
	endfunction
	generate
		for (t = 0; $unsigned(t) < AxiMaxReads; t = t + 1) begin : gen_read_upsizer
			reg [1:0] r_state_d;
			reg [1:0] r_state_q;
			reg [13:0] r_req_d;
			reg [13:0] r_req_q;
			assign idle_read_upsizer[t] = (r_state_q == 2'd0) || (r_state_q == 2'd1);
			reg [(AxiSlvPortStrbWidth * 8) - 1:0] r_data;
			always @(*) begin
				r_state_d = r_state_q;
				r_req_d = r_req_q;
				mst_ar_tran[t] = r_req_q[13];
				mst_ar_id[t * AxiIdWidth+:AxiIdWidth] = r_req_q[13].id;
				mst_ar_valid_tran[t] = r_req_q[12];
				mst_req_ar_err[t] = r_req_q[11];
				slv_r_tran[t] = 1'sb0;
				slv_r_tran[t].id = mst_resp.r.id;
				slv_r_tran[t].resp = mst_resp.r.resp;
				slv_r_tran[t].user = mst_resp.r.user;
				arb_slv_ar_gnt_tran[t] = 1'b0;
				mst_r_ready_tran[t] = 1'b0;
				slv_r_valid_tran[t] = 1'b0;
				if (mst_ar_valid_tran[t] && mst_ar_ready_tran[t]) begin
					r_req_d[12] = 1'b0;
					r_req_d[11] = 1'b0;
				end
				r_data = 1'sb0;
				case (r_state_q)
					2'd0: begin
						r_req_d[13] = 1'sb0;
						if (arb_slv_ar_req && (idx_ar_upsizer == t)) begin
							arb_slv_ar_gnt_tran[t] = 1'b1;
							if (inject_aw_into_ar)
								r_state_d = 2'd1;
							else begin
								r_state_d = 2'd2;
								r_req_d[13] = slv_req_i.ar;
								r_req_d[12] = 1'b1;
								r_req_d[10-:8] = slv_req_i.ar.len;
								r_req_d[2-:3] = slv_req_i.ar.size;
								case (r_req_d[13].burst)
									axi_pkg_BURST_INCR:
										if (axi_pkg_modifiable(r_req_d[13].cache)) begin
											if (r_req_d[13].len != {$bits(type(r_req_d[13].len)) {1'sb0}}) begin : sv2v_autoblock_1
												reg [AxiAddrWidth - 1:0] start_addr;
												reg [AxiAddrWidth - 1:0] end_addr;
												start_addr = axi_pkg_aligned_addr(r_req_d[13].addr, AxiMstPortMaxSize);
												end_addr = axi_pkg_aligned_addr(axi_pkg_beat_addr(r_req_d[13].addr, r_req_d[2-:3], r_req_d[10-:8], r_req_d[13].burst, r_req_d[10-:8]), AxiMstPortMaxSize);
												r_req_d[13].len = (end_addr - start_addr) >> AxiMstPortMaxSize;
												r_req_d[13].size = AxiMstPortMaxSize;
												r_state_d = 2'd3;
											end
										end
									axi_pkg_BURST_FIXED: r_state_d = 2'd2;
									axi_pkg_BURST_WRAP: begin
										r_state_d = 2'd2;
										r_req_d[11] = 1'b1;
										if (r_req_d[13].len == {$bits(type(r_req_d[13].len)) {1'sb0}})
											r_req_d[11] = 1'b0;
									end
								endcase
							end
						end
					end
					2'd1: begin
						r_req_d[13].id = w_req_q[15].id;
						r_req_d[13].addr = w_req_q[15].addr;
						r_req_d[13].size = w_req_q[2-:3];
						r_req_d[13].burst = w_req_q[15].burst;
						r_req_d[13].len = w_req_q[10-:8];
						r_req_d[13].lock = w_req_q[15].lock;
						r_req_d[13].cache = w_req_q[15].cache;
						r_req_d[13].prot = w_req_q[15].prot;
						r_req_d[13].qos = w_req_q[15].qos;
						r_req_d[13].region = w_req_q[15].region;
						r_req_d[13].user = w_req_q[15].user;
						r_req_d[12] = 1'b0;
						r_req_d[10-:8] = w_req_q[10-:8];
						r_req_d[2-:3] = w_req_q[2-:3];
						r_state_d = 2'd2;
						case (r_req_d[13].burst)
							axi_pkg_BURST_INCR:
								if (axi_pkg_modifiable(r_req_d[13].cache)) begin
									if (r_req_d[13].len != {$bits(type(r_req_d[13].len)) {1'sb0}}) begin : sv2v_autoblock_2
										reg [AxiAddrWidth - 1:0] start_addr;
										reg [AxiAddrWidth - 1:0] end_addr;
										start_addr = axi_pkg_aligned_addr(r_req_d[13].addr, AxiMstPortMaxSize);
										end_addr = axi_pkg_aligned_addr(axi_pkg_beat_addr(r_req_d[13].addr, r_req_d[2-:3], r_req_d[10-:8], r_req_d[13].burst, r_req_d[10-:8]), AxiMstPortMaxSize);
										r_req_d[13].len = (end_addr - start_addr) >> AxiMstPortMaxSize;
										r_req_d[13].size = AxiMstPortMaxSize;
										r_state_d = 2'd3;
									end
								end
							axi_pkg_BURST_FIXED: r_state_d = 2'd2;
							axi_pkg_BURST_WRAP: begin
								r_state_d = 2'd2;
								r_req_d[11] = 1'b1;
								if (r_req_d[13].len == {$bits(type(r_req_d[13].len)) {1'sb0}})
									r_req_d[11] = 1'b0;
							end
						endcase
					end
					2'd2, 2'd3:
						if (!r_req_q[12]) begin
							if ((mst_resp.r_valid && (idx_r_upsizer == t)) && r_upsizer_valid) begin : sv2v_autoblock_3
								reg [AxiAddrWidth - 1:0] mst_port_offset;
								reg [AxiAddrWidth - 1:0] slv_port_offset;
								mst_port_offset = (AxiMstPortStrbWidth == 1 ? {cf_math_pkg_idx_width(AxiMstPortStrbWidth) * $bits(type(r_req_q[13].addr[0])) {1'sb0}} : r_req_q[13].addr[cf_math_pkg_idx_width(AxiMstPortStrbWidth) - 1:0]);
								slv_port_offset = (AxiSlvPortStrbWidth == 1 ? {cf_math_pkg_idx_width(AxiSlvPortStrbWidth) * $bits(type(r_req_q[13].addr[0])) {1'sb0}} : r_req_q[13].addr[cf_math_pkg_idx_width(AxiSlvPortStrbWidth) - 1:0]);
								slv_r_valid_tran[t] = 1'b1;
								slv_r_tran[t].last = mst_resp.r.last && (r_req_q[10-:8] == 0);
								begin : sv2v_autoblock_4
									reg signed [31:0] b;
									for (b = 0; b < AxiMstPortStrbWidth; b = b + 1)
										if (((b >= mst_port_offset) && ((b - mst_port_offset) < (1 << r_req_q[2-:3]))) && (((b + slv_port_offset) - mst_port_offset) < AxiSlvPortStrbWidth))
											r_data[((b + slv_port_offset) - mst_port_offset) * 8+:8] = mst_resp.r.data[8 * b+:8];
								end
								slv_r_tran[t].data = r_data;
								if (slv_r_ready_tran[t]) begin
									r_req_d[10-:8] = r_req_q[10-:8] - 1;
									case (r_req_q[13].burst)
										axi_pkg_BURST_INCR: r_req_d[13].addr = axi_pkg_aligned_addr(r_req_q[13].addr, r_req_q[2-:3]) + (1 << r_req_q[2-:3]);
										axi_pkg_BURST_FIXED: r_req_d[13].addr = r_req_q[13].addr;
									endcase
									case (r_state_q)
										2'd2: mst_r_ready_tran[t] = 1'b1;
										2'd3:
											if ((r_req_q[10-:8] == 0) || (axi_pkg_aligned_addr(r_req_d[13].addr, AxiMstPortMaxSize) != axi_pkg_aligned_addr(r_req_q[13].addr, AxiMstPortMaxSize)))
												mst_r_ready_tran[t] = 1'b1;
									endcase
									if (r_req_q[10-:8] == {8 {1'sb0}})
										r_state_d = 2'd0;
								end
							end
						end
				endcase
			end
			always @(posedge clk_i or negedge rst_ni)
				if (!rst_ni) begin
					r_state_q <= 2'd0;
					r_req_q <= 1'sb0;
				end
				else begin
					r_state_q <= r_state_d;
					r_req_q <= r_req_d;
				end
		end
	endgenerate
	reg [1:0] w_state_d;
	reg [1:0] w_state_q;
	reg [(AxiMstPortStrbWidth * 8) - 1:0] w_data;
	always @(*) begin
		inject_aw_into_ar_req = 1'b0;
		w_state_d = w_state_q;
		w_req_d = w_req_q;
		mst_req.aw = w_req_q[15];
		mst_req.aw_valid = w_req_q[14];
		slv_resp_o.aw_ready = 1'sb0;
		mst_req_aw_err = w_req_q[13];
		mst_req.w = w_req_q[12];
		mst_req.w_valid = w_req_q[11];
		slv_resp_o.w_ready = 1'sb0;
		w_data = w_req_q[12].data;
		slv_resp_o.b = mst_resp.b;
		slv_resp_o.b_valid = mst_resp.b_valid;
		mst_req.b_ready = slv_req_i.b_ready;
		if (mst_req.aw_valid && mst_resp.aw_ready) begin
			w_req_d[14] = 1'b0;
			w_req_d[13] = 1'b0;
		end
		case (w_state_q)
			2'd1, 2'd2: begin
				if (mst_req.w_valid && mst_resp.w_ready) begin
					w_data = 1'sb0;
					w_req_d[12] = 1'sb0;
					w_req_d[11] = 1'b0;
				end
				if (!w_req_q[14]) begin
					slv_resp_o.w_ready = ~mst_req.w_valid || mst_resp.w_ready;
					if (slv_req_i.w_valid && slv_resp_o.w_ready) begin : sv2v_autoblock_5
						reg [AxiAddrWidth - 1:0] mst_port_offset;
						reg [AxiAddrWidth - 1:0] slv_port_offset;
						mst_port_offset = (AxiMstPortStrbWidth == 1 ? {cf_math_pkg_idx_width(AxiMstPortStrbWidth) * $bits(type(w_req_q[15].addr[0])) {1'sb0}} : w_req_q[15].addr[cf_math_pkg_idx_width(AxiMstPortStrbWidth) - 1:0]);
						slv_port_offset = (AxiSlvPortStrbWidth == 1 ? {cf_math_pkg_idx_width(AxiSlvPortStrbWidth) * $bits(type(w_req_q[15].addr[0])) {1'sb0}} : w_req_q[15].addr[cf_math_pkg_idx_width(AxiSlvPortStrbWidth) - 1:0]);
						begin : sv2v_autoblock_6
							reg signed [31:0] b;
							for (b = 0; b < AxiMstPortStrbWidth; b = b + 1)
								if (((b >= mst_port_offset) && ((b - mst_port_offset) < (1 << w_req_q[2-:3]))) && (((b + slv_port_offset) - mst_port_offset) < AxiSlvPortStrbWidth)) begin
									w_data[b * 8+:8] = slv_req_i.w.data[8 * ((b + slv_port_offset) - mst_port_offset)+:8];
									w_req_d[12].strb[b] = slv_req_i.w.strb[(b + slv_port_offset) - mst_port_offset];
								end
						end
						w_req_d[10-:8] = w_req_q[10-:8] - 1;
						w_req_d[12].data = w_data;
						w_req_d[12].last = w_req_q[10-:8] == 0;
						w_req_d[12].user = slv_req_i.w.user;
						case (w_req_q[15].burst)
							axi_pkg_BURST_INCR: w_req_d[15].addr = axi_pkg_aligned_addr(w_req_q[15].addr, w_req_q[2-:3]) + (1 << w_req_q[2-:3]);
							axi_pkg_BURST_FIXED: w_req_d[15].addr = w_req_q[15].addr;
						endcase
						case (w_state_q)
							2'd1: w_req_d[11] = 1'b1;
							2'd2:
								if ((w_req_q[10-:8] == 0) || (axi_pkg_aligned_addr(w_req_d[15].addr, AxiMstPortMaxSize) != axi_pkg_aligned_addr(w_req_q[15].addr, AxiMstPortMaxSize)))
									w_req_d[11] = 1'b1;
						endcase
					end
				end
