				w_req_d[14] = 1'b1;
				w_req_d[10-:8] = slv_req_i.aw.len;
				w_req_d[2-:3] = slv_req_i.aw.size;
				case (slv_req_i.aw.burst)
					axi_pkg_BURST_INCR:
						if (axi_pkg_modifiable(slv_req_i.aw.cache)) begin
							if (slv_req_i.aw.len != {$bits(type(slv_req_i.aw.len)) {1'sb0}}) begin : sv2v_autoblock_7
								reg [AxiAddrWidth - 1:0] start_addr;
								reg [AxiAddrWidth - 1:0] end_addr;
								start_addr = axi_pkg_aligned_addr(slv_req_i.aw.addr, AxiMstPortMaxSize);
