								w_state_d = 2'd2;
							end
						end
					axi_pkg_BURST_FIXED: w_state_d = 2'd1;
					axi_pkg_BURST_WRAP: begin
						w_state_d = 2'd1;
						w_req_d[13] = 1'b1;
						if (slv_req_i.aw.len == {$bits(type(slv_req_i.aw.len)) {1'sb0}})
							w_req_d[13] = 1'b0;
					end
				endcase
			end
		end
	end
	always @(posedge clk_i or negedge rst_ni)
		if (!rst_ni) begin
			w_state_q <= 2'd0;
			w_req_q <= 1'sb0;
		end
		else begin
			w_state_q <= w_state_d;
			w_req_q <= w_req_d;
		end
endmodule
