		if (!rst_ni)
			aw_id_q <= 1'sb0;
		else
			aw_id_q <= aw_id_d;
	always @(posedge clk_i or negedge rst_ni)
		if (!rst_ni)
			state_q <= 2'd0;
		else
			state_q <= state_d;
