module axi_isolate (
	clk_i,
	rst_ni,
	slv_req_i,
	slv_resp_o,
	mst_req_o,
	mst_resp_i,
	isolate_i,
	isolated_o
);
	parameter [31:0] NumPending = 32'd16;
	input clk_i;
	input rst_ni;
	input slv_req_i;
	output reg slv_resp_o;
	output reg mst_req_o;
	input mst_resp_i;
	input isolate_i;
	output isolated_o;
	parameter [31:0] CounterWidth = $clog2(NumPending + 32'd1) + 32'd1;
	reg [1:0] state_aw_d;
	reg [1:0] state_aw_q;
	reg [1:0] state_ar_d;
	reg [1:0] state_ar_q;
