	reg update_ar_state;
	reg [CounterWidth - 1:0] pending_aw_d;
	reg [CounterWidth - 1:0] pending_aw_q;
	reg update_aw_cnt;
	reg [CounterWidth - 1:0] pending_w_d;
	reg [CounterWidth - 1:0] pending_w_q;
	reg update_w_cnt;
	reg connect_w;
	reg [CounterWidth - 1:0] pending_ar_d;
	reg [CounterWidth - 1:0] pending_ar_q;
	reg update_ar_cnt;
	always @(posedge clk_i or negedge rst_ni)
		if (!rst_ni)
			pending_aw_q <= 1'sb0;
		else if (update_aw_cnt)
			pending_aw_q <= pending_aw_d;
	always @(posedge clk_i or negedge rst_ni)
		if (!rst_ni)
			pending_w_q <= 1'sb0;
		else if (update_w_cnt)
			pending_w_q <= pending_w_d;
	always @(posedge clk_i or negedge rst_ni)
		if (!rst_ni)
			pending_ar_q <= 1'sb0;
		else if (update_ar_cnt)
			pending_ar_q <= pending_ar_d;
	always @(posedge clk_i or negedge rst_ni)
