		pending_aw_d = pending_aw_q;
		update_aw_cnt = 1'b0;
		pending_w_d = pending_w_q;
		update_w_cnt = 1'b0;
		connect_w = 1'b0;
		pending_ar_d = pending_ar_q;
		update_ar_cnt = 1'b0;
		if (mst_req_o.aw_valid && (state_aw_q == 2'd0)) begin
			pending_aw_d = pending_aw_d + 1;
			update_aw_cnt = 1'b1;
			pending_w_d = pending_w_d + 1;
			update_w_cnt = 1'b1;
			connect_w = 1'b1;
			if (mst_req_o.aw.atop[axi_pkg_ATOP_R_RESP]) begin
				pending_ar_d = pending_ar_d + 1;
				update_ar_cnt = 1'b1;
			end
		end
		if ((mst_req_o.w_valid && mst_resp_i.w_ready) && mst_req_o.w.last) begin
			pending_w_d = pending_w_d - 1;
			update_w_cnt = 1'b1;
		end
		if (mst_resp_i.b_valid && mst_req_o.b_ready) begin
			pending_aw_d = pending_aw_d - 1;
			update_aw_cnt = 1'b1;
		end
		if (mst_req_o.ar_valid && (state_ar_q == 2'd0)) begin
			pending_ar_d = pending_ar_d + 1;
			update_ar_cnt = 1'b1;
		end
		if ((mst_resp_i.r_valid && mst_req_o.r_ready) && mst_resp_i.r.last) begin
			pending_ar_d = pending_ar_d - 1;
			update_ar_cnt = 1'b1;
		end
