		slv_resp_o = mst_resp_i;
		case (state_aw_q)
			2'd0:
				if (((pending_aw_q >= sv2v_cast_6B650(NumPending)) || (pending_ar_q >= sv2v_cast_6B650(2 * NumPending))) || (pending_w_q >= sv2v_cast_6B650(NumPending))) begin
