				mst_req_o.aw = 1'sb0;
				mst_req_o.aw_valid = 1'b0;
				slv_resp_o.aw_ready = 1'b0;
				if (pending_aw_q == {CounterWidth {1'sb0}}) begin
					state_aw_d = 2'd3;
					update_aw_state = 1'b1;
				end
			end
			2'd3: begin
				mst_req_o.aw = 1'sb0;
				mst_req_o.aw_valid = 1'b0;
				slv_resp_o.aw_ready = 1'b0;
				slv_resp_o.b = 1'sb0;
				slv_resp_o.b_valid = 1'b0;
				mst_req_o.b_ready = 1'b0;
				if (!isolate_i) begin
					state_aw_d = 2'd0;
					update_aw_state = 1'b1;
				end
			end
			default:
				;
		endcase
		if ((pending_w_q == {CounterWidth {1'sb0}}) && !connect_w) begin
			mst_req_o.w = 1'sb0;
			mst_req_o.w_valid = 1'b0;
