						update_ar_state = 1'b1;
					end
				end
				else if (slv_req_i.ar_valid && !mst_resp_i.ar_ready) begin
					state_ar_d = 2'd1;
					update_ar_state = 1'b1;
				end
				else if (isolate_i) begin
					state_ar_d = 2'd2;
					update_ar_state = 1'b1;
				end
			2'd1: begin
				mst_req_o.ar_valid = 1'b1;
				if (mst_resp_i.ar_ready) begin
					update_ar_state = 1'b1;
					state_ar_d = (isolate_i ? 2'd2 : 2'd0);
				end
			end
			2'd2: begin
				mst_req_o.ar = 1'sb0;
				mst_req_o.ar_valid = 1'b0;
				slv_resp_o.ar_ready = 1'b0;
				if (pending_ar_q == {CounterWidth {1'sb0}}) begin
					state_ar_d = 2'd3;
					update_ar_state = 1'b1;
				end
			end
			2'd3: begin
				mst_req_o.ar = 1'sb0;
				mst_req_o.ar_valid = 1'b0;
				slv_resp_o.ar_ready = 1'b0;
				slv_resp_o.r = 1'sb0;
				slv_resp_o.r_valid = 1'b0;
				mst_req_o.r_ready = 1'b0;
				if (!isolate_i) begin
					state_ar_d = 2'd0;
					update_ar_state = 1'b1;
				end
			end
			default:
				;
		endcase
	end
	assign isolated_o = (state_aw_q == 2'd3) && (state_ar_q == 2'd3);
endmodule
