module axi_serializer_486C0 (
	clk_i,
	rst_ni,
	slv_req_i,
	slv_resp_o,
	mst_req_o,
	mst_resp_i
);
	parameter [31:0] MaxReadTxns = 32'd0;
	parameter [31:0] MaxWriteTxns = 32'd0;
	parameter [31:0] AxiIdWidth = 32'd0;
	input clk_i;
	input rst_ni;
	input slv_req_i;
	output reg slv_resp_o;
	output reg mst_req_o;
	input mst_resp_i;
	wire rd_fifo_full;
	wire rd_fifo_empty;
	reg rd_fifo_push;
	wire rd_fifo_pop;
	wire wr_fifo_full;
	wire wr_fifo_empty;
	reg wr_fifo_push;
	wire wr_fifo_pop;
	wire [AxiIdWidth - 1:0] b_id;
	wire [AxiIdWidth - 1:0] r_id;
	reg [AxiIdWidth - 1:0] ar_id;
	reg [1:0] state_q;
	reg [1:0] state_d;
	parameter axi_pkg_ATOP_NONE = 2'b00;
	parameter axi_pkg_ATOP_R_RESP = 32'd5;
	always @(*) begin
		state_d = state_q;
		rd_fifo_push = 1'b0;
		wr_fifo_push = 1'b0;
		mst_req_o = slv_req_i;
		slv_resp_o = mst_resp_i;
		mst_req_o.aw.id = 1'sb0;
		mst_req_o.ar.id = 1'sb0;
		ar_id = slv_req_i.ar.id;
		slv_resp_o.b.id = b_id;
		slv_resp_o.r.id = r_id;
		mst_req_o.ar_valid = 1'b0;
		slv_resp_o.ar_ready = 1'b0;
		mst_req_o.aw_valid = 1'b0;
		slv_resp_o.aw_ready = 1'b0;
		case (state_q)
			2'b00, 2'b10: begin
				if (state_q == 2'b10) begin
					if ((((wr_fifo_empty && rd_fifo_empty) || (wr_fifo_pop && rd_fifo_pop)) || (wr_fifo_empty && rd_fifo_pop)) || (wr_fifo_pop && rd_fifo_empty))
						state_d = 2'b00;
				end
				if ((state_q == 2'b00) || (state_d == 2'b00)) begin
					mst_req_o.ar_valid = slv_req_i.ar_valid & ~rd_fifo_full;
					slv_resp_o.ar_ready = mst_resp_i.ar_ready & ~rd_fifo_full;
					rd_fifo_push = mst_req_o.ar_valid & mst_resp_i.ar_ready;
					if (slv_req_i.aw_valid) begin
						if (slv_req_i.aw.atop[5:4] == axi_pkg_ATOP_NONE) begin
							mst_req_o.aw_valid = ~wr_fifo_full;
							slv_resp_o.aw_ready = mst_resp_i.aw_ready & ~wr_fifo_full;
							wr_fifo_push = mst_req_o.aw_valid & mst_resp_i.aw_ready;
						end
						else if (!mst_req_o.ar_valid || (mst_req_o.ar_valid && mst_resp_i.ar_ready))
							state_d = 2'b01;
					end
				end
			end
			2'b01:
				if (wr_fifo_empty && rd_fifo_empty) begin
					mst_req_o.aw_valid = 1'b1;
					slv_resp_o.aw_ready = mst_resp_i.aw_ready;
					wr_fifo_push = mst_resp_i.aw_ready;
					if (slv_req_i.aw.atop[axi_pkg_ATOP_R_RESP]) begin
						ar_id = slv_req_i.aw.id;
						rd_fifo_push = mst_resp_i.aw_ready;
					end
					if (mst_resp_i.aw_ready)
						state_d = 2'b10;
				end
			default:
				;
		endcase
		slv_resp_o.b_valid = mst_resp_i.b_valid & ~wr_fifo_empty;
		mst_req_o.b_ready = slv_req_i.b_ready & ~wr_fifo_empty;
		slv_resp_o.r_valid = mst_resp_i.r_valid & ~rd_fifo_empty;
		mst_req_o.r_ready = slv_req_i.r_ready & ~rd_fifo_empty;
