		.clk_i(clk_i),
		.rst_ni(rst_ni),
		.flush_i(1'b0),
		.testmode_i(1'b0),
		.data_i(ar_id),
		.push_i(rd_fifo_push),
		.full_o(rd_fifo_full),
		.data_o(r_id),
		.empty_o(rd_fifo_empty),
		.pop_i(rd_fifo_pop),
		.usage_o()
	);
	assign rd_fifo_pop = (slv_resp_o.r_valid & slv_req_i.r_ready) & slv_resp_o.r.last;
	fifo_v3_92B55_4DA67 #(
		.dtype_AxiIdWidth(AxiIdWidth),
		.FALL_THROUGH(1'b0),
		.DEPTH(MaxWriteTxns)
	) i_wr_id_fifo(
		.clk_i(clk_i),
		.rst_ni(rst_ni),
		.flush_i(1'b0),
		.testmode_i(1'b0),
		.data_i(slv_req_i.aw.id),
		.push_i(wr_fifo_push),
		.full_o(wr_fifo_full),
		.data_o(b_id),
		.empty_o(wr_fifo_empty),
		.pop_i(wr_fifo_pop),
		.usage_o()
	);
	assign wr_fifo_pop = slv_resp_o.b_valid & slv_req_i.b_ready;
	always @(posedge clk_i or negedge rst_ni)
		if (!rst_ni)
			state_q <= 2'b00;
		else
			state_q <= state_d;
endmodule
