			target_address[0] = 1'b0;
		branch_result_o = next_pc;
		resolved_branch_o[132-:64] = pc_i;
		if (branch_valid_i) begin
			resolved_branch_o[68-:64] = (branch_comp_res_i ? target_address : next_pc);
