module lsu_bypass (
	clk_i,
	rst_ni,
	flush_i,
	lsu_req_i,
	lsu_req_valid_i,
	pop_ld_i,
	pop_st_i,
	lsu_ctrl_o,
	ready_o
);
	input clk_i;
	input rst_ni;
	input flush_i;
	parameter cva6_config_pkg_CVA6ConfigNrScoreboardEntries = 8;
	parameter ariane_pkg_NR_SB_ENTRIES = cva6_config_pkg_CVA6ConfigNrScoreboardEntries;
	parameter ariane_pkg_TRANS_ID_BITS = 3;
	parameter cva6_config_pkg_CVA6ConfigXlen = 64;
	parameter riscv_XLEN = cva6_config_pkg_CVA6ConfigXlen;
	parameter riscv_VLEN = 64;
	input [152:0] lsu_req_i;
	input lsu_req_valid_i;
	input pop_ld_i;
	input pop_st_i;
	output reg [152:0] lsu_ctrl_o;
	output ready_o;
	reg [305:0] mem_n;
	reg [305:0] mem_q;
	reg read_pointer_n;
	reg read_pointer_q;
	reg write_pointer_n;
	reg write_pointer_q;
	reg [1:0] status_cnt_n;
	reg [1:0] status_cnt_q;
	wire empty;
	assign empty = status_cnt_q == 0;
	assign ready_o = empty;
	always @(*) begin : sv2v_autoblock_1
		reg [1:0] status_cnt;
		reg write_pointer;
		reg read_pointer;
		status_cnt = status_cnt_q;
		write_pointer = write_pointer_q;
		read_pointer = read_pointer_q;
		mem_n = mem_q;
		if (lsu_req_valid_i) begin
			mem_n[write_pointer_q * 153+:153] = lsu_req_i;
			write_pointer = write_pointer + 1;
			status_cnt = status_cnt + 1;
		end
		if (pop_ld_i) begin
			mem_n[(read_pointer_q * 153) + 152] = 1'b0;
			read_pointer = read_pointer + 1;
			status_cnt = status_cnt - 1;
		end
		if (pop_st_i) begin
			mem_n[(read_pointer_q * 153) + 152] = 1'b0;
			read_pointer = read_pointer + 1;
			status_cnt = status_cnt - 1;
		end
		if (pop_st_i && pop_ld_i)
			mem_n = 1'sb0;
