	assign op_b_zero = op_b_i == 0;
	assign op_a_sign = op_a_i[WIDTH - 1];
	assign op_b_sign = op_b_i[WIDTH - 1];
	assign lzc_a_input = ((opcode_i[0] & op_a_sign) & (op_a_i == -$signed(1)) ? {~op_a_i, 1'b1} : (opcode_i[0] & op_a_sign ? {~op_a_i, 1'b0} : op_a_i));
