	input [3:0] rd_hit_oh_i;
	reg [2:0] state_d;
	reg [2:0] state_q;
	wire [48:0] address_tag_d;
	reg [48:0] address_tag_q;
	wire [2:0] address_idx_d;
	reg [2:0] address_idx_q;
	wire [3:0] address_off_d;
	reg [3:0] address_off_q;
	wire [3:0] vld_data_d;
	reg [3:0] vld_data_q;
	reg save_tag;
	wire rd_req_d;
	reg rd_req_q;
	wire rd_ack_d;
	reg rd_ack_q;
	wire [1:0] data_size_d;
	reg [1:0] data_size_q;
	assign vld_data_d = (rd_req_q ? rd_vld_bits_i : vld_data_q);
	assign address_tag_d = (save_tag ? req_port_i[191-:32'd49] : address_tag_q);
	assign address_idx_d = (req_port_o[130] ? req_port_i[198:196] : address_idx_q);
	assign address_off_d = (req_port_o[130] ? req_port_i[195:192] : address_off_q);
	assign data_size_d = (req_port_o[130] ? req_port_i[4-:2] : data_size_q);
	assign rd_tag_o = address_tag_d;
	assign rd_idx_o = address_idx_d;
	assign rd_off_o = address_off_d;
	wire [64:1] sv2v_tmp_05984;
	assign sv2v_tmp_05984 = rd_data_i;
	always @(*) req_port_o[127-:64] = sv2v_tmp_05984;
	wire [64:1] sv2v_tmp_F26A2;
	assign sv2v_tmp_F26A2 = rd_user_i;
	always @(*) req_port_o[63-:ariane_pkg_DCACHE_USER_WIDTH] = sv2v_tmp_F26A2;
	wire [1:1] sv2v_tmp_A4D2E;
	assign sv2v_tmp_A4D2E = 1'sb0;
	always @(*) req_port_o[128-:1] = sv2v_tmp_A4D2E;
	assign miss_vld_bits_o = vld_data_q;
	assign miss_paddr_o = {address_tag_q, address_idx_q, address_off_q};
	assign miss_size_o = (miss_nc_o ? data_size_q : 3'b111);
	function automatic [64:0] sv2v_cast_65;
		input reg [64:0] inp;
		sv2v_cast_65 = inp;
	endfunction
	function automatic ariane_pkg_range_check;
		input reg [63:0] base;
		input reg [63:0] len;
		input reg [63:0] address;
		ariane_pkg_range_check = (address >= base) && (address < (sv2v_cast_65(base) + len));
	endfunction
	function automatic ariane_pkg_is_inside_cacheable_regions;
		input reg [6433:0] Cfg;
		input reg [63:0] address;
		reg [15:0] pass;
		begin
			pass = 1'sb0;
			begin : sv2v_autoblock_1
				reg [31:0] k;
				for (k = 0; k < Cfg[2177-:32]; k = k + 1)
					pass[k] = ariane_pkg_range_check(Cfg[1122 + (k * 64)+:64], Cfg[98 + (k * 64)+:64], address);
			end
			ariane_pkg_is_inside_cacheable_regions = |pass;
		end
	endfunction
	assign miss_nc_o = ~cache_en_i | ~ariane_pkg_is_inside_cacheable_regions(ArianeCfg, {{'d8 {1'b0}}, address_tag_q, {ariane_pkg_DCACHE_INDEX_WIDTH {1'b0}}});
	assign miss_we_o = 1'sb0;
	assign miss_wdata_o = 1'sb0;
	assign miss_wuser_o = 1'sb0;
	assign miss_id_o = RdTxId;
	assign rd_req_d = rd_req_o;
	assign rd_ack_d = rd_ack_i;
	assign rd_tag_only_o = 1'sb0;
	always @(*) begin : p_fsm
		state_d = state_q;
		save_tag = 1'b0;
		rd_req_o = 1'b0;
		miss_req_o = 1'b0;
		req_port_o[129] = 1'b0;
		req_port_o[130] = 1'b0;
		case (state_q)
			3'd0:
				if (req_port_i[14]) begin
					rd_req_o = 1'b1;
					if (rd_ack_i) begin
						state_d = 3'd1;
						req_port_o[130] = 1'b1;
					end
				end
			3'd1, 3'd7: begin
				rd_req_o = 1'b1;
				if (req_port_i[1]) begin
					state_d = 3'd0;
					req_port_o[129] = 1'b1;
				end
				else if (req_port_i[0] | (state_q == 3'd7)) begin
					save_tag = state_q != 3'd7;
					if (wr_cl_vld_i || !rd_ack_q)
						state_d = 3'd6;
					else if (|rd_hit_oh_i && cache_en_i) begin
						state_d = 3'd0;
						req_port_o[129] = 1'b1;
						if (rd_ack_i && req_port_i[14]) begin
							state_d = 3'd1;
							req_port_o[130] = 1'b1;
						end
					end
					else
						state_d = 3'd2;
				end
			end
			3'd2: begin
				miss_req_o = 1'b1;
				if (req_port_i[1]) begin
					req_port_o[129] = 1'b1;
					if (miss_ack_i)
						state_d = 3'd4;
					else
						state_d = 3'd5;
				end
				else if (miss_replay_i)
					state_d = 3'd6;
				else if (miss_ack_i)
					state_d = 3'd3;
			end
			3'd3:
				if (req_port_i[1]) begin
					req_port_o[129] = 1'b1;
					if (miss_rtrn_vld_i)
						state_d = 3'd0;
					else
						state_d = 3'd4;
				end
				else if (miss_rtrn_vld_i) begin
					state_d = 3'd0;
					req_port_o[129] = 1'b1;
				end
			3'd6: begin
				rd_req_o = 1'b1;
				if (req_port_i[1]) begin
					req_port_o[129] = 1'b1;
					state_d = 3'd0;
				end
				else if (rd_ack_i)
					state_d = 3'd7;
			end
			3'd5: begin
				miss_req_o = 1'b1;
				if (miss_replay_i)
					state_d = 3'd0;
				else if (miss_ack_i)
					state_d = 3'd4;
			end
			3'd4:
				if (miss_rtrn_vld_i)
