	always @(posedge clk_i or negedge rst_ni) begin : p_regs
		if (!rst_ni) begin
			state_q <= 3'd0;
			address_tag_q <= 1'sb0;
			address_idx_q <= 1'sb0;
			address_off_q <= 1'sb0;
			vld_data_q <= 1'sb0;
			data_size_q <= 1'sb0;
			rd_req_q <= 1'sb0;
			rd_ack_q <= 1'sb0;
		end
		else begin
			state_q <= state_d;
			address_tag_q <= address_tag_d;
			address_idx_q <= address_idx_d;
			address_off_q <= address_off_d;
			vld_data_q <= vld_data_d;
			data_size_q <= data_size_d;
			rd_req_q <= rd_req_d;
			rd_ack_q <= rd_ack_d;
		end
	end
endmodule
