	wire [0:0] wr_cl_nc_off;
	wire [2:0] wbuffer_hit_idx;
	wire [1:0] rd_hit_idx;
	assign cmp_en_d = |vld_req & ~vld_we;
	assign wbuffer_cmp_addr = (wr_cl_vld_i ? {wr_cl_tag_i, wr_cl_idx_i, wr_cl_off_i} : {rd_tag, bank_idx_q, bank_off_q});
