	assign wbuffer_ruser = wbuffer_data_i[(wbuffer_hit_idx * 210) + 92-:64];
	assign wbuffer_be = (|wbuffer_hit_oh ? wbuffer_data_i[(wbuffer_hit_idx * 210) + 20-:8] : {8 {1'sb0}});
	generate
		if (AxiCompliant) begin : gen_axi_off
			assign wr_cl_off = (wr_cl_nc_i ? (AxiDataWidth == riscv_XLEN ? 1'b0 : wr_cl_off_i[AXI_OFFSET_WIDTH - 1:riscv_XLEN_ALIGN_BYTES]) : wr_cl_off_i[3:riscv_XLEN_ALIGN_BYTES]);
		end
		else begin : gen_piton_off
			assign wr_cl_off = wr_cl_off_i[3:3];
		end
	endgenerate
	always @(*)
