				end
			end
		end
		else begin : genblk1
			wire [1:1] sv2v_tmp_6821D;
			assign sv2v_tmp_6821D = 1'b1;
			always @(*) allow_o = sv2v_tmp_6821D;
		end
	endgenerate
endmodule
module pmp_entry (
	addr_i,
	conf_addr_i,
	conf_addr_prev_i,
	conf_addr_mode_i,
	match_o
);
	parameter [31:0] PLEN = 56;
	parameter [31:0] PMP_LEN = 54;
	input [PLEN - 1:0] addr_i;
	input [PMP_LEN - 1:0] conf_addr_i;
	input [PMP_LEN - 1:0] conf_addr_prev_i;
	input [1:0] conf_addr_mode_i;
	output reg match_o;
	wire [PLEN - 1:0] conf_addr_n;
	wire [$clog2(PLEN) - 1:0] trail_ones;
	assign conf_addr_n = ~conf_addr_i;
	lzc #(
		.WIDTH(PLEN),
		.MODE(1'b0)
	) i_lzc(
		.in_i(conf_addr_n),
		.cnt_o(trail_ones),
		.empty_o()
	);
	always @(*)
		case (conf_addr_mode_i)
			2'b01:
				if ((addr_i >= (conf_addr_prev_i << 2)) && (addr_i < (conf_addr_i << 2)))
					match_o = 1'b1;
				else
					match_o = 1'b0;
			2'b10, 2'b11: begin : sv2v_autoblock_1
				reg [PLEN - 1:0] base;
				reg [PLEN - 1:0] mask;
				reg [31:0] size;
				if (conf_addr_mode_i == 2'b10)
					size = 2;
				else
					size = trail_ones + 3;
				mask = 1'sb1 << size;
				base = (conf_addr_i << 2) & mask;
				match_o = ((addr_i & mask) == base ? 1'b1 : 1'b0);
			end
			2'b00: match_o = 1'b0;
			default: match_o = 0;
		endcase
endmodule
module sram (
	clk_i,
	rst_ni,
	req_i,
	we_i,
	addr_i,
	wuser_i,
	wdata_i,
	be_i,
	ruser_o,
	rdata_o
);
	parameter DATA_WIDTH = 64;
	parameter USER_WIDTH = 1;
	parameter USER_EN = 0;
	parameter NUM_WORDS = 1024;
	parameter SIM_INIT = "none";
	parameter OUT_REGS = 0;
	parameter DROMAJO_RAM = 0;
	input clk_i;
	input rst_ni;
	input req_i;
	input we_i;
	input [$clog2(NUM_WORDS) - 1:0] addr_i;
	input [USER_WIDTH - 1:0] wuser_i;
	input [DATA_WIDTH - 1:0] wdata_i;
	input [((DATA_WIDTH + 7) / 8) - 1:0] be_i;
	output reg [USER_WIDTH - 1:0] ruser_o;
	output reg [DATA_WIDTH - 1:0] rdata_o;
	parameter DATA_WIDTH_ALIGNED = ((DATA_WIDTH + 63) / 64) * 64;
	parameter USER_WIDTH_ALIGNED = DATA_WIDTH_ALIGNED;
	parameter BE_WIDTH_ALIGNED = ((((DATA_WIDTH + 7) / 8) + 7) / 8) * 8;
	reg [DATA_WIDTH_ALIGNED - 1:0] wdata_aligned;
	reg [USER_WIDTH_ALIGNED - 1:0] wuser_aligned;
	reg [BE_WIDTH_ALIGNED - 1:0] be_aligned;
	wire [DATA_WIDTH_ALIGNED - 1:0] rdata_aligned;
	wire [USER_WIDTH_ALIGNED - 1:0] ruser_aligned;
	always @(*) begin : p_align
		wdata_aligned = 1'sb0;
		wuser_aligned = 1'sb0;
		be_aligned = 1'sb0;
		wdata_aligned[DATA_WIDTH - 1:0] = wdata_i;
		wuser_aligned[USER_WIDTH - 1:0] = wuser_i;
		be_aligned[BE_WIDTH_ALIGNED - 1:0] = be_i;
		rdata_o = rdata_aligned[DATA_WIDTH - 1:0];
		ruser_o = ruser_aligned[USER_WIDTH - 1:0];
	end
	genvar k;
	generate
		for (k = 0; k < ((DATA_WIDTH + 63) / 64); k = k + 1) begin : gen_cut
			if (DROMAJO_RAM) begin : gen_dromajo
				dromajo_ram #(
					.ADDR_WIDTH($clog2(NUM_WORDS)),
					.DATA_DEPTH(NUM_WORDS),
					.OUT_REGS(0)
				) i_ram(
					.Clk_CI(clk_i),
					.Rst_RBI(rst_ni),
					.CSel_SI(req_i),
					.WrEn_SI(we_i),
					.BEn_SI(be_aligned[k * 8+:8]),
					.WrData_DI(wdata_aligned[k * 64+:64]),
					.Addr_DI(addr_i),
					.RdData_DO(rdata_aligned[k * 64+:64])
				);
				if (USER_EN) begin : gen_dromajo_user
					dromajo_ram #(
						.ADDR_WIDTH($clog2(NUM_WORDS)),
						.DATA_DEPTH(NUM_WORDS),
						.OUT_REGS(0)
					) i_ram_user(
						.Clk_CI(clk_i),
						.Rst_RBI(rst_ni),
						.CSel_SI(req_i),
						.WrEn_SI(we_i),
						.BEn_SI(be_aligned[k * 8+:8]),
						.WrData_DI(wuser_aligned[k * 64+:64]),
						.Addr_DI(addr_i),
						.RdData_DO(ruser_aligned[k * 64+:64])
					);
				end
			end
			else begin : gen_mem
				tc_sram_wrapper #(
					.NumWords(NUM_WORDS),
					.DataWidth(64),
					.ByteWidth(32'd8),
					.NumPorts(32'd1),
					.Latency(32'd1),
					.SimInit(SIM_INIT),
					.PrintSimCfg(1'b0)
				) i_tc_sram_wrapper(
					.clk_i(clk_i),
					.rst_ni(rst_ni),
					.req_i(req_i),
					.we_i(we_i),
					.be_i(be_aligned[k * 8+:8]),
					.wdata_i(wdata_aligned[k * 64+:64]),
					.addr_i(addr_i),
					.rdata_o(rdata_aligned[k * 64+:64])
				);
				if (USER_EN) begin : gen_mem_user
					tc_sram_wrapper #(
						.NumWords(NUM_WORDS),
						.DataWidth(64),
						.ByteWidth(32'd8),
						.NumPorts(32'd1),
						.Latency(32'd1),
						.SimInit(SIM_INIT),
						.PrintSimCfg(1'b0)
					) i_tc_sram_wrapper_user(
						.clk_i(clk_i),
						.rst_ni(rst_ni),
						.req_i(req_i),
						.we_i(we_i),
						.be_i(be_aligned[k * 8+:8]),
						.wdata_i(wuser_aligned[k * 64+:64]),
						.addr_i(addr_i),
						.rdata_o(ruser_aligned[k * 64+:64])
					);
				end
				else begin : genblk1
					assign ruser_aligned[k * 64+:64] = 1'sb0;
				end
			end
		end
	endgenerate
endmodule
module tc_sram_wrapper (
	clk_i,
	rst_ni,
	req_i,
	we_i,
	addr_i,
	wdata_i,
	be_i,
	rdata_o
);
	parameter [31:0] NumWords = 32'd1024;
	parameter [31:0] DataWidth = 32'd128;
	parameter [31:0] ByteWidth = 32'd8;
	parameter [31:0] NumPorts = 32'd2;
	parameter [31:0] Latency = 32'd1;
	parameter SimInit = "none";
	parameter [0:0] PrintSimCfg = 1'b0;
	parameter [31:0] AddrWidth = (NumWords > 32'd1 ? $clog2(NumWords) : 32'd1);
	parameter [31:0] BeWidth = ((DataWidth + ByteWidth) - 32'd1) / ByteWidth;
	input clk_i;
	input rst_ni;
	input [NumPorts - 1:0] req_i;
	input [NumPorts - 1:0] we_i;
	input [(NumPorts * AddrWidth) - 1:0] addr_i;
	input [(NumPorts * DataWidth) - 1:0] wdata_i;
	input [(NumPorts * BeWidth) - 1:0] be_i;
	output [(NumPorts * DataWidth) - 1:0] rdata_o;
	tc_sram #(
		.NumWords(NumWords),
		.DataWidth(DataWidth),
		.ByteWidth(ByteWidth),
		.NumPorts(NumPorts),
		.Latency(Latency),
		.SimInit(SimInit),
		.PrintSimCfg(PrintSimCfg)
	) i_tc_sram(
		.clk_i(clk_i),
		.rst_ni(rst_ni),
		.req_i(req_i),
		.we_i(we_i),
		.be_i(be_i),
		.wdata_i(wdata_i),
		.addr_i(addr_i),
		.rdata_o(rdata_o)
	);
endmodule
